  "تحجز موعدًا": "You book an appointment",
  "تختار نوع العمل والموعد المناسب من الموقع، وترفق صورًا للمشكلة إن وجدت، ثم ترسل الطلب لنا على واتساب برسالة جاهزة.": "Choose the type of work and a suitable time on the site, attach photos of the problem if any, then send us the request on WhatsApp with a ready message.",
