  "تستلم عرض سعر مكتوبًا": "You get a written quote",
  "يوضح العرض المواد والكميات ومدة التنفيذ والسعر. تراه على صفحتك في الموقع، ولا نبدأ قبل موافقتك.": "The quote lists materials, quantities, duration and price. You see it on your page on the site, and we don't start before you approve.",
