  "نلتزم بموعد البدء والتسليم المتفق عليه، ومسؤول واحد يتابع معك حتى استلام العمل.": "We keep to the agreed start and handover dates, with one person following up with you until handover.",
  "فريق أردني يعمل في البناء والصيانة والدهان والأعمال المعدنية للبيوت والشركات.": "A Jordanian team working in construction, maintenance, painting and metalwork for homes and companies.",
