  "تسريب مياه، رطوبة، تشققات، مشاكل كهرباء أو سباكة. نزور الموقع، نحدد سبب المشكلة، ونعطيك تقريرًا وسعر الإصلاح قبل البدء.": "Water leaks, damp, cracks, electrical or plumbing problems. We visit the site, find the cause, and give you a report and a repair price before we start.",
  "وصف العطل وصور إن وُجدت": "Fault description and photos if any",
  "دهان شقق وبيوت ومكاتب: دهان جديد أو تجديد، بلاستيك أو زيتي أو شمواه، مع الديكورات إن أردت.": "Painting apartments, houses and offices: new paint or renewal, plastic, oil-based or chamois, with decorations if you like.",
