  "تعبئة الطلب تأخذ دقيقتين. تختار اليوم والساعة بنفسك، ويصلنا الحجز مباشرة ونتواصل معك لتأكيده.": "Filling in the request takes two minutes. You choose the day and hour yourself, the booking reaches us directly and we contact you to confirm.",
