  "الطلب الطارئ يُجدول بأولوية خلال نفس اليوم إن أمكن، ورسومه أعلى من الكشف العادي.": "Emergency requests are scheduled with priority on the same day when possible, and cost more than a regular inspection.",
  "نحن فريق أردني يعمل في البناء والصيانة والدهان والأعمال المعدنية. نزور الموقع، نكشف على المشكلة، ونعطيك سعرًا مكتوبًا قبل أن نبدأ. نعمل مع البيوت والشقق والفلل، ومع المصانع والشركات بعقود صيانة سنوية تشمل المرافق والكهرباء والأرضيات الإيبوكسي ومتطلبات GMP وISO. كل عمل نستلمه يكون له مسؤول واحد يتابعه معك من الكشف حتى التسليم، وتقدر تشوف حالة طلبك وعروض الأسعار من صفحتك على الموقع.": "We are a Jordanian team working in construction, maintenance, painting and metalwork. We visit the site, inspect the problem, and give you a written price before we start. We work with houses, apartments and villas, and with factories and companies on annual maintenance contracts covering utilities, electrical, epoxy floors and GMP and ISO requirements. Every job has one person following up with you from inspection to handover, and you can see your request status and quotes from your page on the site.",
  "احجز كشفًا على موقعك، واستلم سعرًا واضحًا قبل البدء. فنيّون معروفون، ومواعيد نلتزم بها.": "Book an on-site inspection and get a clear price before we start. Known technicians, and appointments we keep.",
