  "هيكل حديد مربع 20×20 ملم، مدهون بطبقة أساس ضد الصدأ وطبقتين دهان فرن. المقعد خشب بلوط معالج للاستخدام الخارجي. الأبعاد: 55 × 60 × 85 سم. يتحمل حتى 130 كغ.": "Square 20×20 mm steel frame with an anti-rust primer and two coats of baked paint. Oak seat treated for outdoor use. Dimensions: 55 × 60 × 85 cm. Holds up to 130 kg.",
