  "وحدة MDF مقاوم للرطوبة بقشرة خشب جوز، درجين بإغلاق هادئ وفتحة خلفية للأسلاك. الطول 180 سم.": "Moisture-resistant MDF unit with walnut veneer, two soft-close drawers and a rear cable opening. Length 180 cm.",
