  "قص ليزر على صاج 2 ملم، دهان إلكتروستاتيك. يمكن تخصيص النص والمقاس عند الطلب. المقاس القياسي 100 × 50 سم.": "Laser-cut 2 mm sheet steel, electrostatic paint. Text and size can be customized on order. Standard size 100 × 50 cm.",
  "أحواض زراعة كورتن (3 قطع)": "Corten planters (set of 3)",
  "ثلاثة أحواض من حديد الكورتن بمقاسات 30 و40 و50 سم، مع فتحات تصريف. تكتسب لون الصدأ الطبيعي مع الوقت دون أن تتآكل.": "Three Corten steel planters in 30, 40 and 50 cm with drainage holes. They take on a natural rust color over time without corroding.",
  "فانوس نحاس مشغول": "Handcrafted brass lantern",
  "فانوس نحاس بزجاج ملون، شغل يدوي. الارتفاع 45 سم، يعمل بشمعة أو لمبة LED.": "Brass lantern with colored glass, handmade. Height 45 cm, works with a candle or an LED bulb.",
  "طاولة عمل صناعية": "Industrial workbench",
  "هيكل حديد 50×50 ملم، سطح صاج 3 ملم مع طبقة خشب، ودرج بقفل. الأبعاد: 180 × 75 × 90 سم. حمولة 500 كغ.": "50×50 mm steel frame, 3 mm sheet top with a wood layer, and a lockable drawer. Dimensions: 180 × 75 × 90 cm. 500 kg load.",
