  "خمسة رفوف قابلة لتغيير الارتفاع، حمولة الرف 200 كغ. مناسب للمستودعات والمحلات. الأبعاد: 100 × 50 × 200 سم.": "Five height-adjustable shelves, 200 kg per shelf. Suits warehouses and shops. Dimensions: 100 × 50 × 200 cm.",
