  // الواجهة الصناعية
  "صيانة الماكينات والمرافق الصناعية": "Machine and industrial facility maintenance",
  "نصون الماكينات وخطوط الإنتاج والمرافق بعقود سنوية أو عند العطل، ونورّد المنتجات والتجهيزات الصناعية التي يحتاجها مصنعك. زيارات مجدولة، تقرير مكتوب بعد كل زيارة، وأولوية حسب أثر العطل على الإنتاج.": "We maintain machines, production lines and facilities on annual contracts or on breakdown, and supply the industrial products and equipment your factory needs. Scheduled visits, a written report after every visit, and priority based on the impact on production.",
  "صيانة الماكينات وخطوط الإنتاج": "Machine & production line maintenance",
  "تشخيص الأعطال وإصلاحها، وصيانة وقائية دورية تقلل التوقف.": "Fault diagnosis and repair, plus regular preventive maintenance that reduces downtime.",
  "منتجات وتجهيزات صناعية": "Industrial products & equipment",
  "طاولات عمل، رفوف تخزين، ملصقات أرضية ومستلزمات للمصانع والمستودعات.": "Workbenches, storage racks, floor markings and supplies for factories and warehouses.",
  "صيانة دورية للتمديدات والمرافق والأنظمة المساندة للإنتاج.": "Regular maintenance of wiring, utilities and production support systems.",
  "تجهيز المرافق والأرضيات الإيبوكسي حسب متطلبات التدقيق.": "Preparing facilities and epoxy floors to audit requirements.",
  "استجابة عاجلة": "Urgent response",
  "فريق يصل بسرعة عند توقف خط إنتاج أو عطل مفاجئ.": "A team that arrives fast when a production line stops or a sudden fault hits.",
  "تقارير مكتوبة": "Written reports",
  "تقرير بعد كل زيارة وسجل كامل لعقدك على صفحتك في الموقع.": "A report after every visit and a full record of your contract on your page.",
  "منتجات مختارة من السوق": "Featured marketplace products",
  "خدمات المباني": "Building services",
  "بناء وصيانة ودهان للبيوت والمنشآت": "Construction, maintenance and painting for homes and facilities",
  "تجهيزات ومستلزمات للمصانع والمستودعات والورش: طاولات عمل، رفوف تخزين، ملصقات أرضية إرشادية ومنتجات صناعية أخرى، مع التوصيل.": "Equipment and supplies for factories, warehouses and workshops: workbenches, storage racks, floor guidance markings and other industrial products, with delivery.",
  "تصفح المنتجات الصناعية": "Browse industrial products",
  "صيانة ماكينات": "Machine maintenance",
  "صيانة وإصلاح الماكينات وخطوط الإنتاج عند العطل، بفنيين يصلون بسرعة وأولوية حسب أثر العطل على الإنتاج، وتقرير مكتوب بعد كل زيارة.": "Maintenance and repair of machines and production lines on breakdown, with technicians who arrive fast, priority based on production impact, and a written report after every visit.",
  "اطلب صيانة عاجلة": "Request urgent maintenance",
  "عقود صيانة للمصانع": "Factory maintenance contracts",
  "زيارات دورية مجدولة للماكينات والمرافق والكهرباء، وتجهيز المنشأة لمتطلبات GMP وISO، مع أولوية الاستجابة عند الأعطال.": "Scheduled visits for machines, utilities and electrical systems, facility preparation for GMP and ISO, and priority response on breakdowns.",
  "بناء وصيانة مباني": "Building works",
  "كشف أعطال البناء، دهان وديكور، بناء وتشطيب، أعمال معدنية وصيانة عامة للبيوت والمنشآت.": "Building fault inspection, painting and decor, construction and finishing, metalwork and general maintenance for homes and facilities.",
  "— حلول صناعية ومقاولات": "— Industrial solutions & contracting",
  "مرحبًا، أريد الاستفسار عن منتجاتكم وخدماتكم": "Hello, I'd like to ask about your products and services",
  "للمصانع والمنشآت الصناعية": "For factories & industrial facilities",
  "تجهيزات ومستلزمات مع التوصيل": "Equipment & supplies, delivered",
