  "منتجات صناعية وصيانة ماكينات ومقاولات في الأردن": "Industrial products, machine maintenance and contracting in Jordan",
  "منتجات صناعية وصيانة ماكينات ومقاولات": "Industrial products, machine maintenance and contracting",
  "نورّد المنتجات والتجهيزات الصناعية، ونصون الماكينات وخطوط الإنتاج بعقود سنوية أو عند العطل، ونكمل معك أعمال البناء والصيانة في عمّان وكل المحافظات.": "We supply industrial products and equipment, maintain machines and production lines on annual contracts or on breakdown, and handle your construction and maintenance work in Amman and all governorates.",
