  "رسالة بهوية فرجار باسم العميل ورمز من 6 أرقام صالح 10 دقائق ولمرة واحدة. هذه معاينة ببيانات تجريبية.": "A Farjar-branded email with the customer's name and a 6-digit code valid for 10 minutes, single use. This preview uses sample data.",
  "البريد غير مفعّل على الخادم بعد. أضف SMTP_HOST وSMTP_USER وSMTP_PASS في إعدادات Render ليبدأ الإرسال الفعلي.": "Email isn't enabled on the server yet. Add SMTP_HOST, SMTP_USER and SMTP_PASS in Render settings to start sending.",
