  // السياسات
  "السياسات": "Policies",
  "سياسة الحجز والطلب": "Booking & order policy",
  "كل ما تحتاج معرفته قبل الحجز أو الطلب، بوضوح ومن غير مفاجآت.": "Everything you need to know before booking or ordering, clearly and with no surprises.",
  "أقسام الصفحة": "Page sections",
  "سياسة الحجز": "Booking policy",
  "سياسة الطلب والتوصيل": "Order & delivery policy",
  "عندك سؤال عن أي بند؟": "Question about any item?",
  "وسنوضحه لك.": "and we'll explain it.",
  "اقرأ سياسة الحجز وضع إشارة على الموافقة لإتمام الحجز": "Read the booking policy and tick the box to agree before confirming",
  "قراءة البنود": "Read the terms",
  "المواعيد، رسوم الكشف، عرض السعر قبل البدء، والتعديل والإلغاء.": "Appointments, inspection fee, a written quote before work starts, and changes or cancellation.",
  "قرأت سياسة الحجز وأوافق عليها": "I have read and agree to the booking policy",
  "بتأكيد الطلب أنت توافق على": "By confirming the order you agree to the",
  "المحتوى والسياسات": "Content & policies",
  "نصوص الصفحة الرئيسية وصفحة نبذة عنا وسياسات الحجز والطلب": "Home page and About texts, and the booking and order policies",
  "كل سطر بند مستقل. اكتب «العنوان: النص» ليظهر العنوان بخط عريض. تظهر في آخر خطوة من الحجز (بخانة موافقة إلزامية) وفي صفحة السياسات.": "Each line is a separate item. Write “Title: text” to show the title in bold. Shown on the last booking step (with a required agreement box) and on the policies page.",
  "تظهر في صفحة السياسات ورابطها في صفحة إتمام الطلب.": "Shown on the policies page and linked from checkout.",
  "اقرأ سياسة الحجز ووافق عليها لإتمام الحجز": "Read and agree to the booking policy to complete the booking",
  "اكتب بنود سياسة الحجز": "Write the booking policy items",
  "اكتب بنود سياسة الطلب": "Write the order policy items",
  "مواعيد الزيارة:": "Visit appointments:",
  "بعد إرسال الحجز نتواصل معك لتأكيد الموعد، وقد نقترح وقتًا بديلًا إذا تعذّر الموعد المختار.": "After you book, we contact you to confirm the appointment, and may suggest another time if the chosen one isn't possible.",
  "رسوم الكشف:": "Inspection fee:",
  "تُدفع للفني نقدًا عند الزيارة، وتغطي الزيارة والتشخيص فقط، وتختلف حسب نوع الطلب (عادي، عاجل، طارئ).": "Paid to the technician in cash at the visit. It covers the visit and diagnosis only, and depends on priority (normal, urgent, emergency).",
  "عرض السعر:": "Quote:",
  "بعد الكشف تستلم عرض سعر مكتوبًا بالمواد ومدة التنفيذ، ولا يبدأ أي عمل ولا تُطلب أي دفعة قبل موافقتك عليه.": "After the inspection you get a written quote with materials and timeline. No work starts and no payment is requested until you approve it.",
  "التعديل والإلغاء:": "Changes & cancellation:",
  "لتغيير الموعد أو إلغائه أبلغنا في أقرب وقت قبل الموعد عبر واتساب أو الهاتف أو من صفحتك في الموقع.": "To reschedule or cancel, tell us as early as possible before the appointment via WhatsApp, phone or your account page.",
  "التواجد في الموقع:": "Access to the site:",
  "يلزم وجود شخص بالغ في الموقع وقت الزيارة وتسهيل الوصول، وإذا تعذّر الدخول نتواصل معك لإعادة الجدولة.": "An adult must be on site at the visit time with access available. If we can't get in, we'll contact you to reschedule.",
  "الصور والملفات:": "Photos & files:",
  "تُستخدم لتقييم العمل فقط، ولا ننشرها دون إذنك.": "Used only to assess the work, and never published without your permission.",
  "بياناتك:": "Your data:",
  "نستخدم رقمك وموقعك للتواصل معك وتنفيذ الزيارة فقط، ولا نشاركها مع أي جهة خارجية.": "We use your number and location only to contact you and carry out the visit, and never share them with third parties.",
  "تأكيد الطلب:": "Order confirmation:",
  "بعد إرسال الطلب نتواصل معك لتأكيده وتحديد موعد التوصيل.": "After you order, we contact you to confirm it and schedule delivery.",
  "الأسعار:": "Prices:",
  "الأسعار المعروضة بالدينار الأردني، وأجرة التوصيل تظهر قبل تأكيد الطلب.": "Prices are in Jordanian dinars, and the delivery fee is shown before you confirm.",
  "الدفع:": "Payment:",
  "عند الاستلام أو بالطرق المعروضة عند إتمام الطلب، ويُسجَّل المبلغ المدفوع على طلبك.": "On delivery or by the methods shown at checkout; the amount paid is recorded on your order.",
  "الاستلام:": "Receiving:",
  "افحص المنتج عند الاستلام، وأبلغ موظف التوصيل أو تواصل معنا فورًا عند وجود أي ضرر أو نقص.": "Inspect the product on delivery, and tell the driver or contact us right away about any damage or missing items.",
  "الإلغاء:": "Cancellation:",
  "يمكن إلغاء الطلب قبل خروجه للتوصيل بالتواصل معنا.": "You can cancel the order before it goes out for delivery by contacting us.",
  "المنتجات المصنوعة حسب الطلب أو القياس لا تُسترجع بعد بدء تصنيعها إلا في حال وجود عيب.": "Made-to-order or custom-sized products can't be returned once production starts, unless defective.",
  // ── السوق الصناعي ──
