  "الحجم": "Size",
  "الموديل": "Model",
  "خيارات المنتج (اللون، المقاس…)": "Product options (color, size…)",
  "العميل يختار قيمة من كل خيار قبل الإضافة للسلة، ويظهر اختياره في السلة والطلب والفاتورة. مثال: اللون ← أحمر، أزرق، رمادي.": "Customers pick one value from each option before adding to cart, and their choice appears in the cart, order and invoice. Example: Color → Red, Blue, Grey.",
