  "المستويات والنقاط جاهزة في قاعدة البيانات وغير مفعّلة الآن — المرحلة الأولى هي التميز الشهري. يمكنك ضبط حدود كل مستوى مسبقًا، وتُسجَّل نقاط المكافآت في سجل النقاط.": "Tiers and points are ready in the database and not active yet — phase one is monthly recognition. You can set each tier's thresholds in advance; reward points are recorded in the points ledger.",
