  "تأكدت من وصول المبلغ في الإيصال المرفق.": "I verified the amount in the attached receipt arrived.",
  "يُعتمد المورد على الباقة المجانية، وتبقى الباقة المطلوبة بانتظار مراجعة الإيصال.": "The supplier is approved on the free plan, and the requested plan stays pending receipt review.",
  "الباقات المدفوعة: حوّل المبلغ عبر CliQ أو تحويل بنكي وأرفق صورة الإيصال ضمن نموذج التسجيل، وتُفعَّل الباقة عند اعتماد الإدارة. يمكنك الترقية لاحقًا من لوحة المورد.": "Paid plans: transfer the amount via CliQ or bank transfer and attach the receipt within the registration form; the plan activates when the admin approves. You can upgrade later from the supplier dashboard.",
  "باقة": "Plan",
  "وصل إيصال الدفع مع طلبك. تراجعه الإدارة مع بيانات شركتك، وتُفعَّل الباقة عند الاعتماد.": "Your payment receipt arrived with your request. The admin reviews it with your company details, and the plan activates on approval.",
  "دفع باقة": "Pay for plan",
  "حوّل المبلغ ثم أرفق صورة الإيصال — يصل مع طلب انضمامك، وتُفعَّل الباقة عند اعتماد الإدارة.": "Transfer the amount, then attach the receipt — it's sent with your join request, and the plan activates when the admin approves.",
