  "الباقات المدفوعة: بعد التسجيل تحوّل المبلغ عبر CliQ أو تحويل بنكي وترفق صورة الإيصال، وتُفعَّل الباقة بعد تأكيد الإدارة. يمكنك الترقية لاحقًا من لوحة المورد.": "Paid plans: after registering, transfer the amount via CliQ or bank transfer and attach the receipt; the plan activates after admin confirmation. You can upgrade later from the supplier dashboard.",
