  "بنك الاتحاد": "Union Bank",
  "حوّل المبلغ عبر CliQ أو تحويل بنكي واكتب رقم الفاتورة في ملاحظة التحويل، ثم ارفع صورة أو PDF لإيصال الدفع. تُفعَّل الخدمة بعد تأكيد الإدارة.": "Transfer the amount via CliQ or bank transfer and write the invoice number in the transfer note, then upload an image or PDF of the payment receipt. The service activates after admin confirmation.",
