  "فحص التصوير الحراري للأسطح والتمديدات": "Thermal imaging inspection of surfaces & installations",
  "تحويل الاختلافات الحرارية غير المرئية خلف الأسطح والجدران إلى خريطة حرارية ملونة بدقة متناهية ودون تكسير.": "Turns invisible temperature differences behind surfaces and walls into a precise colour heat map — with no breaking.",
  "كشف تسريبات المياه الساخنة والباردة وخطوط التدفئة تحت البلاط": "Detects hot/cold water and heating-line leaks under tiles",
  "رصد مسار النزيز والرطوبة داخل الجدران والخرسانة": "Traces seepage and moisture paths inside walls and concrete",
  "تقييم كفاءة العزل الحراري ونقاط الضعف بالأبواب والنوافذ": "Assesses thermal insulation and weak points at doors and windows",
  "فحص نقاط السخونة والحمل الزائد في لوحات الكهرباء والقواطع": "Checks hot spots and overloads in electrical panels and breakers",
  "فحص صلابة وقوة الخرسانة (مطرقة شميدت)": "Concrete hardness & strength test (Schmidt hammer)",
  "إطلاق صدمة قياسية مرتدة وحساب قوة الارتداد لتحويلها لقراءات تبين المقاومة الضغطية للباطون دون تدمير الهيكل.": "Fires a standard rebound impact and converts the rebound into readings of concrete compressive strength — non-destructively.",
  "تقييم المتانة والسلامة الإنشائية للأعمدة والأسقف والقواعد": "Evaluates durability and structural safety of columns, slabs and footings",
  "كشف الضعف الخرساني المخفي قبل حدوث أي تشققات خطيرة": "Reveals hidden concrete weakness before serious cracks appear",
  "فحص جاهزية المبنى للتوسع أو بناء طوابق إضافية": "Checks if the building is ready for expansion or extra floors",
  "توثيق رقمي معتمد يدمج في التقرير الفني": "Certified digital readings included in the technical report",
  "فحص واختبار ضغط شبكات المواسير والسباكة": "Pipe & plumbing network pressure testing",
  "ربط شبكة التغذية أو التدفئة بمضخة هيدروليكية ومراقبة ثبات الضغط عبر ساعة حساس رصد دقيقة.": "Connects the supply or heating network to a hydraulic pump and monitors pressure stability on a precision gauge.",
  "الجزم التام بسلامة خطوط التغذية والتدفئة": "Confirms the integrity of supply and heating lines with certainty",
  "فحص قوة تحمل الأكواع واللحامات لمنع التسريب مستقبلًا": "Tests elbows and joints to prevent future leaks",
  "حماية العميل من تكاليف الصيانة عبر الفحص الوقائي المبكر": "Saves maintenance costs through early preventive testing",
  "تحديد الخط المتضرر بدقة لتفادي الحفر العشوائي": "Pinpoints the damaged line to avoid random digging",
  "فحص كشف التسريبات الصوتي (HY929)": "Acoustic leak detection (HY929)",
  "تضخيم الترددات الصوتية المجهرية الناجمة عن خروج الماء تحت الأرض أو الجدران عبر مجسات إبرية وأرضية.": "Amplifies the micro-sounds of escaping water under floors or in walls using needle and ground probes.",
  "الوصول المباشر للنقطة الصفرية للتسريب بدقة عالية جدًا": "Locates the exact leak point with very high accuracy",
  "إلغاء الحاجة لتكسير السيراميك أو الجدران بشكل عشوائي": "No need to randomly break tiles or walls",
